import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    static final class FixedWindowLimiter {
        private final int capacity;
        private final Map<String, Integer> counts = new HashMap<>();

        FixedWindowLimiter(int capacity) {
            this.capacity = capacity;
        }

        synchronized boolean allow(String key) {
            int used = counts.getOrDefault(key, 0);
            if (used >= capacity) {
                return false;
            }
            counts.put(key, used + 1);
            return true;
        }
    }

    static final AtomicInteger REQUEST_ID = new AtomicInteger();

    public static void main(String[] args) throws Exception {
        HttpServer backend = HttpServer.create(new InetSocketAddress(0), 0);
        backend.createContext("/orders/42", exchange -> {
            String rid = exchange.getRequestHeaders().getFirst("X-Request-Id");
            String auth = exchange.getRequestHeaders().getFirst("Authorization");
            respond(exchange, 200, "backend path=/orders/42,rid=" + rid + ",auth=" + auth);
        });
        backend.start();

        FixedWindowLimiter limiter = new FixedWindowLimiter(2);
        HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();
        HttpServer gateway = HttpServer.create(new InetSocketAddress(0), 0);
        int backendPort = backend.getAddress().getPort();
        gateway.createContext("/", exchange -> {
            try {
                handleGateway(exchange, backendPort, limiter, client);
            } catch (InterruptedException interrupted) {
                Thread.currentThread().interrupt();
                respond(exchange, 500, "gateway interrupted");
            } catch (Exception failure) {
                respond(exchange, 502, "gateway error=" + failure.getClass().getSimpleName());
            }
        });
        gateway.start();

        try {
            int gatewayPort = gateway.getAddress().getPort();
            System.out.println(call(gatewayPort, "/missing", null));
            System.out.println(call(gatewayPort, "/api/orders/42", null));
            System.out.println(call(gatewayPort, "/api/orders/42", "Bearer demo"));
            System.out.println(call(gatewayPort, "/api/orders/42", "Bearer demo"));
            System.out.println(call(gatewayPort, "/api/orders/42", "Bearer demo"));
        } finally {
            gateway.stop(0);
            backend.stop(0);
        }
    }

    static void handleGateway(com.sun.net.httpserver.HttpExchange exchange, int backendPort,
                              FixedWindowLimiter limiter, HttpClient client) throws IOException, InterruptedException {
        String path = exchange.getRequestURI().getPath();
        if (!path.startsWith("/api/")) {
            respond(exchange, 404, "no route");
            return;
        }

        String auth = exchange.getRequestHeaders().getFirst("Authorization");
        if (auth == null || auth.isBlank()) {
            respond(exchange, 401, "unauthorized");
            return;
        }

        if (!limiter.allow(auth)) {
            respond(exchange, 429, "rate limited route=orders");
            return;
        }

        String rewrittenPath = path.substring("/api".length());
        String requestId = "gw-" + REQUEST_ID.incrementAndGet();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create("http://127.0.0.1:" + backendPort + rewrittenPath))
                .timeout(Duration.ofSeconds(2))
                .header("Authorization", auth)
                .header("X-Request-Id", requestId)
                .GET()
                .build();
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        exchange.getResponseHeaders().add("X-Gateway-Route", "orders");
        respond(exchange, response.statusCode(), "gateway route=orders -> " + response.body());
    }

    static String call(int port, String path, String auth) throws Exception {
        HttpRequest.Builder builder = HttpRequest.newBuilder()
                .uri(URI.create("http://127.0.0.1:" + port + path))
                .timeout(Duration.ofSeconds(2))
                .GET();
        if (auth != null) {
            builder.header("Authorization", auth);
        }
        HttpResponse<String> response = HttpClient.newHttpClient().send(builder.build(), HttpResponse.BodyHandlers.ofString());
        return response.statusCode() + " " + response.body();
    }

    static void respond(com.sun.net.httpserver.HttpExchange exchange, int status, String body) throws IOException {
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        exchange.sendResponseHeaders(status, bytes.length);
        try (OutputStream out = exchange.getResponseBody()) {
            out.write(bytes);
        }
    }
}
